DO $$
DECLARE cid uuid := 'a0000000-0000-0000-0000-000000000001';
BEGIN

-- Reset previously seeded KB rows (tagged) so re-running is clean.
DELETE FROM public.kb_articles WHERE company_id = cid AND tags @> ARRAY['seed:guia_v1'];

