VALUES (cid, 'cotinguiba-08', 'Cotinguiba 08', 'duplex', 'Cotinguiba', 'São Miguel dos Milagres', 6, 2, '2 camas queen + 2 bicama', '2 banheiros + 1 lavabo', 'Dúplex moderno a poucos passos da praia, com piscina privativa.', 'Dúplex a passos do mar, ideal para momentos de conforto e lazer. Acomoda até 6 pessoas em 2 suítes.', ARRAY['2 suíte(s) com ar-condicionado', 'Sala de TV', 'Internet de alta velocidade em toda a casa', 'Cozinha totalmente equipada', 'Piscina privativa', 'Churrasqueira portátil a carvão']::text[], ARRAY['Proibido som alto', 'Proibido animais na piscina', 'Proibido fumar', 'Proibido fazer festas', 'Proibido acumular lixo na acomodação', 'O descumprimento das regras pode gerar multa']::text[], '15:00', '11:00', 'Não reembolsável.', 'Cotinguiba 08', '08cotinguiba', 'fechadura_facial', '172839#', 'Check-in a partir das 15h. Estacione em uma vaga livre em frente ao condomínio, vá à portaria com fechadura inteligente facial, posicione o rosto na câmera e a porta destrava. Senha da fechadura eletrônica do apartamento: 172839# (sempre com # no final). Check-out às 11h.')
ON CONFLICT (company_id, unit_code) DO UPDATE SET
  name = EXCLUDED.name, property_type = EXCLUDED.property_type, condo = EXCLUDED.condo, region = EXCLUDED.region, max_guests = EXCLUDED.max_guests, suites = EXCLUDED.suites, beds = EXCLUDED.beds, bathrooms = EXCLUDED.bathrooms, short_description = EXCLUDED.short_description, description = EXCLUDED.description, amenities = EXCLUDED.amenities, house_rules = EXCLUDED.house_rules, check_in_time = EXCLUDED.check_in_time, check_out_time = EXCLUDED.check_out_time, cancellation_policy = EXCLUDED.cancellation_policy, wifi_ssid = EXCLUDED.wifi_ssid, wifi_password = EXCLUDED.wifi_password, access_method = EXCLUDED.access_method, door_code = EXCLUDED.door_code, access_instructions = EXCLUDED.access_instructions, updated_at = now();

