INSERT INTO public.kb_articles (company_id, scope, category, title, content, data, visibility, tags, sort_order)
VALUES (cid, 'region', 'como_chegar', 'Como chegar a São Miguel dos Milagres', 'Os aeroportos mais próximos são Maceió e Recife, ambos com fácil acesso à região (o aeroporto de Maragogi ainda não opera). Indicamos serviços de transfer entre o aeroporto e a acomodação. Para quem vem de carro alugado, siga sempre a localização enviada pela nossa equipe pelo WhatsApp.', NULL, 'public', ARRAY['transfer', 'aeroporto', 'chegada', 'seed:guia_v1']::text[], 10);

INSERT INTO public.kb_articles (company_id, scope, category, title, content, data, visibility, tags, sort_order)
VALUES (cid, 'region', 'checkin', 'Check-in, check-out e cancelamento', 'Check-in a partir das 15h e check-out às 11h. Antes de sair, confira se não esqueceu pertences, desligue equipamentos e ar-condicionado. Para prolongar a estadia, fale conosco com antecedência pelo WhatsApp. Política de cancelamento: não reembolsável. O método de acesso (fechadura facial, chaves na portaria ou cofre) e a senha são enviados ao hóspede com reserva confirmada.', NULL, 'public', ARRAY['checkin', 'checkout', 'cancelamento', 'horario', 'seed:guia_v1']::text[], 20);

INSERT INTO public.kb_articles (company_id, scope, category, title, content, data, visibility, tags, sort_order)
VALUES (cid, 'region', 'enxoval', 'Roupa de cama e banho (enxoval)', 'Oferecemos enxoval completo, ajustado à quantidade de pessoas da reserva. Para estadias com diária mínima de 7 dias, fazemos a troca do enxoval sem custo. Caso alguma peça seja danificada, pode ser aplicada taxa de reposição.', NULL, 'public', ARRAY['enxoval', 'cama', 'banho', 'toalha', 'seed:guia_v1']::text[], 30);

INSERT INTO public.kb_articles (company_id, scope, category, title, content, data, visibility, tags, sort_order)
VALUES (cid, 'region', 'locomocao', 'Como se locomover e estacionamento', 'Há serviços de táxi e transfer na região (podemos recomendar opções confiáveis). A acomodação fica a poucos passos da praia, cerca de 5 minutos de caminhada. O estacionamento fica em frente ao condomínio — use qualquer vaga livre.', NULL, 'public', ARRAY['taxi', 'transfer', 'estacionamento', 'caminhada', 'seed:guia_v1']::text[], 40);

